components.css:
.ds-sign-up-page{font-family:var(--font-lexend,Lexend),"Avenir Next",Verdana,sans-serif;font-size:1rem;line-height:1.625rem;color:var(--text-primary,#131a3d);background:var(--bg-base,#f5f8f6);}
:where(.ds-sign-up-page) :is(h1,p){margin:0;}
:where(.ds-sign-up-page) :is(section,fieldset,input,button){box-sizing:border-box;}
.ds-sign-up-stage,.ds-sign-up-ribbon,.ds-sign-up-dot{box-sizing:border-box;}
:where(.ds-sign-up-page) fieldset{min-width:0;margin:0;padding:0;border:0;}
:where(.ds-sign-up-page) legend{padding:0;}
:where(.ds-sign-up-page) button{background:transparent;border:0;font:inherit;}
.ds-sign-up-js-notice{margin-top:1rem;}
.ds-sign-up-label{display:block;font-size:.875rem;font-weight:500;line-height:1.25rem;}
.ds-sign-up-field-help{color:var(--text-muted,#55605d);font-size:.8125rem;line-height:1.25rem;overflow-wrap:anywhere;}
.ds-sign-up-input::placeholder{opacity:1;}
.ds-sign-up-help a{display:inline-flex;min-height:2.75rem;align-items:center;color:var(--accent-strong,#0a7566);text-decoration:underline;text-underline-offset:.2em;}
.ds-sign-up-help a:hover{text-decoration-thickness:2px;}
.ds-sign-up-page :is(button,a):focus-visible{outline:2px solid var(--focus-ring,#0a7566);outline-offset:2px;}
.ds-sign-up-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border-width:0;}
.ds-sign-up-page {
  --ds-sign-up-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  container: ds-sign-up-page / inline-size;
  width: 100%;
}
.ds-sign-up-stage {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: calc(100svh - 4.5625rem);
  padding: 4rem 1.25rem 6rem;
}
.ds-sign-up-card {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 32.5rem;
  padding: 2.75rem 2.75rem 2.25rem;
  border: 1px solid var(--border-default,#c9d3ce);
  border-radius: 1.75rem;
  background: var(--bg-surface,#ffffff);
  box-shadow:
    0 1px 2px color-mix(in srgb, var(--text-primary,#131a3d) 4%, transparent),
    0 2.5rem 5rem -2.5rem
      color-mix(in srgb, var(--brand-navy,#1e2a78) 35%, transparent);
}
.ds-sign-up-welcome {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 0.625rem;
  color: var(--accent-strong,#0a7566);
  font-size: 0.8125rem;
  font-weight: 500;
}
.ds-sign-up-welcome::before {
  content: "";
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--accent-primary,#2eccb0);
}
.ds-sign-up-card h1 {
  margin-bottom: 0.5rem;
  color: var(--brand-navy,#1e2a78);
  font-size: 2.75rem;
  font-weight: 600;
  line-height: 1.05;
  letter-spacing: -0.035em;
  text-align: center;
  text-wrap: balance;
}
.ds-sign-up-lede {
  margin-bottom: 1.75rem;
  color: var(--text-muted,#55605d);
  font-size: 0.875rem;
  text-align: center;
}
.ds-sign-up-card > section + .ds-sign-up-form {
  margin-top: 1.5rem;
}
.ds-sign-up-choices {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
  min-width: 0;
  margin-bottom: 1.375rem;
}
.ds-sign-up-choices legend {
  margin-bottom: 0.5rem;
  font-size: 0.875rem;
  font-weight: 500;
}
.ds-sign-up-option {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.875rem 1rem;
  border: 1px solid var(--border-control,#55605d);
  border-radius: 0.875rem;
  background: var(--bg-surface,#ffffff);
  color: var(--text-primary,#131a3d);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
}
.ds-sign-up-option input {
  width: 1rem;
  height: 1rem;
  flex: none;
  margin-top: 0.1875rem;
  accent-color: var(--brand-navy,#1e2a78);
}
.ds-sign-up-option small {
  display: block;
  margin-top: 0.125rem;
  color: var(--text-muted,#55605d);
  font-size: 0.8125rem;
  font-weight: 400;
}
.ds-sign-up-option[data-later] {
  grid-column: 1 / -1;
  padding-block: 0.625rem;
}
.ds-sign-up-option:has(input:checked) {
  border-color: var(--brand-navy,#1e2a78);
  background: color-mix(in srgb, var(--brand-navy,#1e2a78) 4%, var(--bg-surface,#ffffff));
}
.ds-sign-up-option:has(input:not(:disabled)):hover {
  border-color: var(--brand-navy,#1e2a78);
}
.ds-sign-up-option:has(input:focus-visible) {
  outline: 2px solid var(--focus-ring,#0a7566);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px
    color-mix(in srgb, var(--accent-primary,#2eccb0) 35%, transparent);
}
.ds-sign-up-field {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-bottom: 1.375rem;
}
.ds-sign-up-field > p {
  font-size: 0.8125rem;
}
.ds-sign-up-form [role="alert"] {
  background: var(--bg-surface,#ffffff);
}
.ds-sign-up-input {
  width: 100%;
  min-width: 0;
  min-height: 3.375rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border-control,#55605d);
  border-radius: 0.875rem;
  background: var(--bg-surface,#ffffff);
  color: var(--text-primary,#131a3d);
  font: inherit;
  font-size: 1rem;
}
.ds-sign-up-input::placeholder {
  color: var(--text-muted,#55605d);
}
.ds-sign-up-input:not(:disabled):hover {
  border-color: var(--brand-navy,#1e2a78);
}
.ds-sign-up-input:focus {
  border-color: var(--brand-navy,#1e2a78);
  box-shadow: 0 0 0 4px
    color-mix(in srgb, var(--accent-primary,#2eccb0) 28%, transparent);
}
.ds-sign-up-input:focus-visible {
  outline: 2px solid var(--focus-ring,#0a7566);
  outline-offset: 2px;
}
.ds-sign-up-password-control {
  position: relative;
}
.ds-sign-up-password-control .ds-sign-up-input {
  padding-inline-end: 4.75rem;
}
.ds-sign-up-toggle {
  position: absolute;
  top: 50%;
  inset-inline-end: 0.25rem;
  min-width: 2.75rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.625rem;
  translate: 0 -50%;
  border-radius: var(--radius-control,.625rem);
  color: var(--brand-navy,#1e2a78);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
}
.ds-sign-up-toggle:hover {
  background: color-mix(in srgb, var(--brand-mint,#a7dccb) 26%, var(--bg-surface,#ffffff));
}
.ds-sign-up-submit {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  width: 100%;
  min-height: 3.5rem;
  margin-top: 0.5rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--brand-navy,#1e2a78);
  border-radius: 0.875rem;
  background: var(--brand-navy,#1e2a78);
  color: var(--text-inverse,#ffffff);
  font-weight: 500;
  cursor: pointer;
  box-shadow: 0 0.5rem 1.25rem -0.625rem
    color-mix(in srgb, var(--brand-navy,#1e2a78) 60%, transparent);
}
.ds-sign-up-submit:not(:disabled):hover {
  background: var(--brand-navy-hover,#192260);
}
.ds-sign-up-submit-arrow {
  display: grid;
  width: 1.625rem;
  height: 1.625rem;
  flex: none;
  place-items: center;
  border-radius: 50%;
  background: var(--accent-primary,#2eccb0);
  color: var(--brand-navy,#1e2a78);
}
.ds-sign-up-form[aria-busy="true"] .ds-sign-up-submit-arrow svg {
  display: none;
}
.ds-sign-up-form[aria-busy="true"] .ds-sign-up-submit-arrow::after {
  content: "";
  width: 0.875rem;
  height: 0.875rem;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
}
.ds-sign-up-fields:disabled
  :is(
    .ds-sign-up-input,
    .ds-sign-up-option,
    .ds-sign-up-submit,
    .ds-sign-up-submit-arrow
  ) {
  transition: none;
  transform: none;
}
.ds-sign-up-fields:disabled
  :is(.ds-sign-up-toggle, .ds-sign-up-submit, .ds-sign-up-option) {
  cursor: not-allowed;
}
.ds-sign-up-fields:disabled .ds-sign-up-submit {
  border-color: var(--border-default,#c9d3ce);
  background: var(--bg-subtle,#e6ece8);
  color: var(--text-muted,#55605d);
  box-shadow: none;
}
.ds-sign-up-help {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.25rem 1.5rem;
  margin-top: 1.75rem;
  padding-top: 1.375rem;
  border-top: 1px solid var(--border-default,#c9d3ce);
  font-size: 0.875rem;
}
.ds-sign-up-help > span {
  color: var(--text-muted,#55605d);
}
.ds-sign-up-artwork,
.ds-sign-up-art {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.ds-sign-up-art {
  overflow: clip;
}
.ds-sign-up-art::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(
    color-mix(in srgb, var(--brand-navy,#1e2a78) 13%, transparent) 1px,
    transparent 1.2px
  );
  background-size: 1.375rem 1.375rem;
  mask-image: radial-gradient(70% 60% at 50% 40%, black 20%, transparent 75%);
}
.ds-sign-up-ribbon {
  position: absolute;
  inset-inline: -10%;
  top: 52%;
  height: 7.5rem;
  rotate: -7deg;
  background: color-mix(in srgb, var(--brand-mint,#a7dccb) 75%, var(--bg-base,#f5f8f6));
  border-bottom: 0.875rem solid
    color-mix(in srgb, var(--brand-navy,#1e2a78) 75%, var(--bg-base,#f5f8f6));
}
.ds-sign-up-float {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.ds-sign-up-float-left {
  left: max(2rem, calc(50% - 35rem));
  top: 7.5rem;
  align-items: flex-end;
}
.ds-sign-up-float-right {
  right: max(2rem, calc(50% - 35rem));
  top: 16.25rem;
  align-items: flex-start;
}
.ds-sign-up-chip {
  padding: 0.4375rem 0.875rem;
  border: 1px solid var(--border-default,#c9d3ce);
  border-radius: calc(infinity * 1px);
  background: var(--bg-surface,#ffffff);
  color: var(--brand-navy,#1e2a78);
  font-size: 0.875rem;
  font-weight: 500;
  white-space: nowrap;
  box-shadow: 0 0.625rem 1.5rem -0.875rem
    color-mix(in srgb, var(--brand-navy,#1e2a78) 35%, transparent);
}
.ds-sign-up-chip-selected {
  border-color: var(--brand-navy,#1e2a78);
  background: var(--brand-navy,#1e2a78);
  color: var(--text-inverse,#ffffff);
}
.ds-sign-up-float-left > :nth-child(1) {
  rotate: -6deg;
}
.ds-sign-up-float-left > :nth-child(3) {
  rotate: 3deg;
  translate: -1.75rem;
}
.ds-sign-up-float-left > :nth-child(4) {
  rotate: -2deg;
  translate: 0.625rem;
}
.ds-sign-up-float-right > :nth-child(1) {
  rotate: 5deg;
}
.ds-sign-up-float-right > :nth-child(2) {
  rotate: -4deg;
  translate: 1.875rem;
}
.ds-sign-up-float-right > :nth-child(4) {
  rotate: 2deg;
  translate: -0.375rem;
}
.ds-sign-up-mini {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem 0.75rem 0.75rem;
  border: 1px solid var(--border-default,#c9d3ce);
  border-radius: 1.125rem;
  background: var(--bg-surface,#ffffff);
  box-shadow: 0 1.125rem 2.25rem -1.25rem
    color-mix(in srgb, var(--brand-navy,#1e2a78) 40%, transparent);
}
.ds-sign-up-mini p {
  color: var(--text-primary,#131a3d);
  font-size: 0.875rem;
  font-weight: 500;
}
.ds-sign-up-mini small {
  display: block;
  color: var(--text-muted,#55605d);
  font-size: 0.8125rem;
  font-weight: 400;
}
.ds-sign-up-float-left .ds-sign-up-mini {
  rotate: -3deg;
  translate: -1.25rem;
}
.ds-sign-up-float-right .ds-sign-up-mini {
  rotate: 3deg;
  translate: 1rem;
}
.ds-sign-up-mini-mark {
  width: 2.5rem;
  height: 2.5rem;
  flex: none;
  border-radius: 50%;
  background: var(--brand-mint,#a7dccb);
}
.ds-sign-up-mini-mark-navy {
  background: var(--brand-navy,#1e2a78);
}
.ds-sign-up-dot {
  position: absolute;
  border-radius: 50%;
}
.ds-sign-up-dot-one {
  width: 1.125rem;
  height: 1.125rem;
  background: var(--accent-primary,#2eccb0);
  left: calc(50% - 20.625rem);
  top: 4.625rem;
}
.ds-sign-up-dot-two {
  width: 0.625rem;
  height: 0.625rem;
  background: var(--brand-navy,#1e2a78);
  right: calc(50% - 19.375rem);
  top: 6rem;
}
.ds-sign-up-dot-four {
  width: 0.75rem;
  height: 0.75rem;
  border: 2px solid var(--brand-navy,#1e2a78);
  left: calc(50% - 18.75rem);
  top: calc(52% + 9.375rem);
}
.ds-sign-up-orb {
  width: 3.5rem;
  height: 3.5rem;
  right: calc(50% - 18.75rem);
  top: calc(52% + 2.5rem);
  background: var(--accent-primary,#2eccb0);
  box-shadow:
    0 0 0 0.4375rem var(--bg-base,#f5f8f6),
    0 1.125rem 1.875rem -0.5rem
      color-mix(in srgb, var(--brand-navy,#1e2a78) 45%, transparent);
}

@media (prefers-reduced-motion: no-preference) {
  .ds-sign-up-input {
    transition:
      border-color 150ms linear,
      box-shadow 200ms var(--ds-sign-up-ease);
  }
  .ds-sign-up-option {
    transition:
      border-color 150ms linear,
      box-shadow 200ms var(--ds-sign-up-ease),
      background-color 150ms linear;
  }
  .ds-sign-up-form[aria-busy="true"] .ds-sign-up-submit-arrow::after {
    animation: ds-sign-up-pending-spin 800ms linear infinite;
  }
  .ds-sign-up-submit {
    transition:
      transform 200ms var(--ds-sign-up-ease),
      box-shadow 200ms var(--ds-sign-up-ease);
  }
  .ds-sign-up-submit-arrow {
    transition: transform 300ms var(--ds-sign-up-ease);
  }
  .ds-sign-up-submit:not(:disabled):hover {
    transform: translateY(-1px);
    box-shadow: 0 0.875rem 1.625rem -0.75rem
      color-mix(in srgb, var(--brand-navy,#1e2a78) 70%, transparent);
  }
  .ds-sign-up-submit:not(:disabled):hover .ds-sign-up-submit-arrow {
    transform: translateX(4px);
  }
  .ds-sign-up-submit:not(:disabled):active {
    transform: scale(0.985);
  }
  .ds-sign-up-float {
    animation: ds-sign-up-bob 7s var(--ds-sign-up-ease) infinite alternate;
    animation-play-state: paused;
  }
  .ds-sign-up-float-right {
    animation-delay: -3s;
  }
  .ds-sign-up-orb {
    animation: ds-sign-up-bob 6s var(--ds-sign-up-ease) infinite alternate;
    animation-play-state: paused;
  }
  .ds-sign-up-art[data-motion-running] :is(.ds-sign-up-float, .ds-sign-up-orb) {
    animation-play-state: running;
  }

}
@keyframes ds-sign-up-bob {
  to {
    transform: translateY(-8px);
  }
}
@keyframes ds-sign-up-pending-spin {
  to {
    transform: rotate(360deg);
  }
}
@container ds-sign-up-page (max-width: 73.75rem) {
  .ds-sign-up-float,
  .ds-sign-up-dot-one,
  .ds-sign-up-dot-two,
  .ds-sign-up-dot-four {
    display: none;
  }
  .ds-sign-up-orb {
    right: 1.25rem;
  }
}
@container ds-sign-up-page (max-width: 56.25rem) {
  .ds-sign-up-stage {
    padding: 1.5rem 1.25rem 4rem;
  }
  .ds-sign-up-card {
    padding: 1.75rem 1.25rem;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }
  .ds-sign-up-card h1 {
    font-size: 2.25rem;
  }
  .ds-sign-up-orb {
    display: none;
  }
  .ds-sign-up-ribbon {
    top: 62%;
  }
}
@container ds-sign-up-page (max-width: 24rem) {
  .ds-sign-up-choices {
    grid-template-columns: minmax(0, 1fr);
  }
  .ds-sign-up-card {
    padding-inline: 0;
  }
}
@media (forced-colors: active) {
  .ds-sign-up-artwork {
    display: none;
  }
  .ds-sign-up-card,
  .ds-sign-up-submit {
    box-shadow: none;
  }
  .ds-sign-up-option,
  .ds-sign-up-input,
  .ds-sign-up-submit,
  .ds-sign-up-toggle {
    border: 1px solid ButtonText;
  }
}

